content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: #f0f2f5;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

.calculator-container {
  width: 100%;
  max-width: 360px;
  background-color: #202020;
  border-radius: 24px;
  overflow: hidden;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
  padding: 24px;
}

.calculator-display {
  background-color: #111111;
  border-radius: 16px;
  padding: 20px;
  margin-bottom: 24px;
  text-align: right;
  min-height: 90px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  word-break: break-all;
  word-wrap: break-word;
}

.display-sub {
  color: #888888;
  font-size: 1rem;
  min-height: 1.2rem;
}

.display-main {
  color: #ffffff;
  font-size: 2.2rem;
  font-weight: 500;
}

.calculator-keypad {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

.calc-btn {
  background-color: #333333;
  color: #ffffff;
  border: none;
  border-radius: 12px;
  font-size: 1.25rem;
  font-weight: 500;
  height: 60px;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
  display: flex;
  align-items: center;
  justify-content: center;
  user-select: none;
}

.calc-btn:hover {
  background-color: #444444;
}

.calc-btn:active {
  transform: scale(0.95);
}

.calc-btn-operator {
  background-color: #ff9500;
  color: #ffffff;
}

.calc-btn-operator:hover {
  background-color: #ffaa22;
}

.calc-btn-clear {
  background-color: #a5a5a5;
  color: #000000;
}

.calc-btn-clear:hover {
  background-color: #b5b5b5;
}

.calc-btn-equals {
  background-color: #ff9500;
  color: #ffffff;
}

.calc-btn-equals:hover {
  background-color: #ffaa22;
}

.calc-btn-zero {
  grid-column: span 2;
  border-radius: 30px;
  justify-content: flex-start;
  padding-left: 24px;
}

import { useState } from 'react';
import './index.css';

export default function App() {
  const [display, setDisplay] = useState<string>('0');
  const [prevValue, setPrevValue] = useState<number | null>(null);
  const [operator, setOperator] = useState<string | null>(null);
  const [waitingForOperand, setWaitingForOperand] = useState<boolean>(false);
  const [subDisplay, setSubDisplay] = useState<string>('');

  const inputDigit = (digit: string) => {
    if (waitingForOperand) {
      setDisplay(digit);
      setWaitingForOperand(false);
    } else {
      setDisplay(display === '0' ? digit : display + digit);
    }
  };

  const inputDecimal = () => {
    if (waitingForOperand) {
      setDisplay('0.');
      setWaitingForOperand(false);
      return;
    }
    if (!display.includes('.')) {
      setDisplay(display + '.');
    }
  };

  const clearAll = () => {
    setDisplay('0');
    setPrevValue(null);
    setOperator(null);
    setWaitingForOperand(false);
    setSubDisplay('');
  };

  const performOperation = (nextOperator: string) => {
    const inputValue = parseFloat(display);

    if (prevValue === null) {
      setPrevValue(inputValue);
    } else if (operator) {
      const currentValue = prevValue || 0;
      const newValue = calculate(currentValue, inputValue, operator);

      setPrevValue(newValue);
      setDisplay(String(newValue));
    }

    setWaitingForOperand(true);
    setOperator(nextOperator);
    setSubDisplay(`${display} ${nextOperator}`);
  };

  const calculate = (firstValue: number, secondValue: number, op: string): number => {
    switch (op) {
      case '+':
        return firstValue + secondValue;
      case '-':
        return firstValue - secondValue;
      case '×':
        return firstValue * secondValue;
      case '÷':
        return secondValue === 0 ? 0 : firstValue / secondValue;
      default:
        return secondValue;
    }
  };

  const handleEquals = () => {
    const inputValue = parseFloat(display);

    if (operator && prevValue !== null) {
      const result = calculate(prevValue, inputValue, operator);
      setDisplay(String(result));
      setSubDisplay(`${prevValue} ${operator} ${inputValue} =`);
      setPrevValue(null);
      setOperator(null);
      setWaitingForOperand(true);
    }
  };

  return (
    <div className="calculator-container">
      <div className="calculator-display">
        <div className="display-sub">{subDisplay}</div>
        <div className="display-main">{display}</div>
      </div>
      <div className="calculator-keypad">
        <button className="calc-btn calc-btn-clear" onClick={clearAll}>
          AC
        </button>
        <button className="calc-btn calc-btn-clear" onClick={() => setDisplay(String(-parseFloat(display)))}>
          +/-
        </button>
        <button className="calc-btn calc-btn-clear" onClick={() => setDisplay(String(parseFloat(display) / 100))}>
          %
        </button>
        <button className="calc-btn calc-btn-operator" onClick={() => performOperation('÷')}>
          ÷
        </button>

        <button className="calc-btn" onClick={() => inputDigit('7')}>7</button>
        <button className="calc-btn" onClick={() => inputDigit('8')}>8</button>
        <button className="calc-btn" onClick={() => inputDigit('9')}>9</button>
        <button className="calc-btn calc-btn-operator" onClick={() => performOperation('×')}>
          ×
        </button>

        <button className="calc-btn" onClick={() => inputDigit('4')}>4</button>
        <button className="calc-btn" onClick={() => inputDigit('5')}>5</button>
        <button className="calc-btn" onClick={() => inputDigit('6')}>6</button>
        <button className="calc-btn calc-btn-operator" onClick={() => performOperation('-')}>
          -
        </button>

        <button className="calc-btn" onClick={() => inputDigit('1')}>1</button>
        <button className="calc-btn" onClick={() => inputDigit('2')}>2</button>
        <button className="calc-btn" onClick={() => inputDigit('3')}>3</button>
        <button className="calc-btn calc-btn-operator" onClick={() => performOperation('+')}>
          +
        </button>

        <button className="calc-btn calc-btn-zero" onClick={() => inputDigit('0')}>
          0
        </button>
        <button className="calc-btn" onClick={inputDecimal}>
          .
        </button>
        <button className="calc-btn calc-btn-equals" onClick={handleEquals}>
          =
        </button>
      </div>
    </div>
  );
}
